import app from 'flarum/forum/app';
import AboutNav from './AboutNav';
import CommunityPage from './CommunityPage';
import { t } from '../../utils/settings';
/**
 * 按 `h2` 标题切分 HTML：之前的内容为引言（放在顶部），每个标题
 * 成为一个带锚点的章节。列表项各自变成一条带编号的“规则”。
 * HTML 来自服务端（fof/pages 页面或管理员文本），已在服务端
 * 净化。
 */
function structure(html) {
  const root = new DOMParser().parseFromString(`<div>${html}</div>`, 'text/html').body.firstElementChild;
  const sections = [];
  const intro = [];
  let current = null;
  const used = new Set();
  const flush = () => {
    if (!current) return;
    let id = 'regra-' + (current.title.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || sections.length + 1);
    while (used.has(id)) id += '-';
    used.add(id);
    sections.push({
      id,
      title: current.title,
      html: current.nodes.join('')
    });
  };
  Array.from(root?.childNodes || []).forEach(node => {
    if (node instanceof HTMLElement && node.tagName === 'H2') {
      flush();
      current = {
        title: node.textContent?.trim() || '',
        nodes: []
      };
      return;
    }
    if (node instanceof HTMLElement && (node.tagName === 'UL' || node.tagName === 'OL')) {
      node.classList.add('LcoyRules-list');
      Array.from(node.children).forEach((li, index) => {
        li.classList.add('LcoyRules-rule');
        li.setAttribute('data-n', String(index + 1));
      });
    }
    const out = node instanceof HTMLElement ? node.outerHTML : node.textContent?.trim() ? `<p>${node.textContent}</p>` : '';
    (current ? current.nodes : intro).push(out);
  });
  flush();
  return {
    intro: intro.join(''),
    sections
  };
}

/**
 * “关于”区域中规则页面的基类（“准则”以及 fof/pages 的额外页面）：
 * 标题、以胶囊按钮呈现的章节索引，以及每节一张卡片。
 * 每个页面只需说明 HTML 的来源和哪个标签处于激活状态。
 */
export default class RulesPage extends CommunityPage {
  html = null;
  pageTitle = null;
  failed = false;
  oninit(vnode) {
    super.oninit(vnode);
    if (this.enabled()) this.load();
  }

  /** API 地址，相对路径（`/lcoy-guidelines`）。 */

  /** AboutNav 中高亮显示的标签。 */

  load() {
    app.request({
      method: 'GET',
      url: `${(app.forum.attribute('apiUrl') || '/api').replace(/\/+$/, '')}${this.endpoint()}`
    }).then(data => {
      this.html = data?.html || '';
      this.pageTitle = data?.title || null;
      this.loaded(data);
    }).catch(() => this.failed = true).finally(() => m.redraw());
  }

  /** 加载完成后执行（额外页面会更新浏览器标签页标题）。 */
  loaded(_data) {}
  content() {
    let body;
    if (this.failed) body = m("p", {
      className: "LcoyCommunity-empty"
    }, t('community.load_error'));else if (this.html === null) body = this.skeleton();else body = this.rules(this.html);
    return m("div", {
      className: "LcoyAbout LcoyGuidelines"
    }, m("header", {
      className: "LcoyAbout-header"
    }, AboutNav(this.activeTab())), body);
  }

  /**
   * 文本尚未到达：标题（已确定）和两张沿用真实类名的规则卡片，
   * 用骨架条代替文字行，使内容到达时正落在骨架所在的位置。
   */
  skeleton() {
    const line = width => m("span", {
      className: "LcoySkeleton LcoySkeleton--line",
      style: {
        width
      }
    });
    return m("div", {
      className: "LcoyRules LcoyRules--loading",
      "aria-busy": "true"
    }, m("h1", {
      className: "LcoyRules-title"
    }, this.title()), m("nav", {
      className: "LcoyRules-toc",
      "aria-hidden": "true"
    }, ['9em', '12em', '8em', '11em', '10em', '7em'].map(width => m("a", null, m("span", {
      className: "LcoySkeleton LcoySkeleton--word",
      style: {
        width
      }
    })))), [['30%', ['100%', '94%', '72%']], ['24%', ['96%', '100%', '58%']]].map(([title, lines]) => m("section", {
      className: "LcoyRules-card"
    }, m("h2", {
      className: "LcoyRules-sectionTitle"
    }, line(title)), m("div", {
      className: "LcoyRules-body Post-body"
    }, m("p", null, lines.map(line))))));
  }
  rules(html) {
    const {
      intro,
      sections
    } = structure(html);
    const title = this.pageTitle || this.title();
    return m("div", {
      className: "LcoyRules"
    }, m("h1", {
      className: "LcoyRules-title"
    }, title), intro && (sections.length ? m("div", {
      className: "LcoyRules-intro Post-body"
    }, m.trust(intro)) : m("section", {
      className: "LcoyRules-card"
    }, m("div", {
      className: "LcoyRules-body Post-body"
    }, m.trust(intro)))), sections.length > 1 && m("nav", {
      className: "LcoyRules-toc",
      "aria-label": title
    }, sections.map(section => m("a", {
      href: `#${section.id}`,
      onclick: e => {
        e.preventDefault();
        document.getElementById(section.id)?.scrollIntoView({
          behavior: 'smooth',
          block: 'start'
        });
      }
    }, section.title))), sections.map(section => m("section", {
      className: "LcoyRules-card",
      id: section.id
    }, m("h2", {
      className: "LcoyRules-sectionTitle"
    }, section.title), m("div", {
      className: "LcoyRules-body Post-body"
    }, m.trust(section.html)))));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/RulesPage', RulesPage);